  "inlineSchema": "// OutcomeTrack Prisma Schema\n// Longitudinal skilling outcomes platform\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// Enums\nenum OutcomeStatus {\n  EMPLOYED\n  SELF_EMPLOYED\n  APPRENTICE\n  LOOKING\n  NOT_WORKING\n  UNKNOWN\n}\n\nenum VerificationStatus {\n  UNKNOWN\n  SELF_REPORTED\n  PROVIDER_CONFIRMED\n  EMPLOYER_CONFIRMED\n  DOCUMENT_VERIFIED\n  SYSTEM_VERIFIED\n  CONFLICT\n}\n\nenum SalaryBand {\n  LT_10K\n  B_10_20K\n  B_20_35K\n  B_35_50K\n  GT_50K\n}\n\nenum NonPlacementReason {\n  NO_JOBS\n  SKILLS_MISMATCH\n  FAMILY\n  HEALTH\n  OTHER\n}\n\nenum FollowupStatus {\n  SCHEDULED\n  SENT\n  RESPONDED\n  FAILED\n  EXPIRED\n}\n\nenum Channel {\n  WHATSAPP\n  SMS\n  EMAIL\n}\n\nenum BotSessionState {\n  AWAITING_STATUS\n  AWAITING_EMPLOYER_NAME\n  AWAITING_ROLE\n  AWAITING_SALARY_BAND\n  AWAITING_NON_PLACEMENT_REASON\n  DONE\n}\n\nenum ActorType {\n  ADMIN\n  TRAINEE\n  EMPLOYER\n  SYSTEM\n}\n\n// Core Tables\nmodel Programme {\n  id        String   @id @default(uuid())\n  name      String\n  code      String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  cohorts   Cohort[]\n\n  @@map(\"programmes\")\n}\n\nmodel Cohort {\n  id          String   @id @default(uuid())\n  programmeId String\n  name        String\n  startDate   DateTime\n  endDate     DateTime\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  programme      Programme       @relation(fields: [programmeId], references: [id])\n  enrolments     Enrolment[]\n  followupEvents FollowupEvent[]\n\n  @@map(\"cohorts\")\n}\n\nmodel Trainee {\n  id        String   @id @default(uuid())\n  publicId  String   @unique @default(uuid())\n  fullName  String\n  phoneE164 String   @unique\n  email     String?\n  district  String\n  language  String   @default(\"EN\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  enrolments       Enrolment[]\n  followupEvents   FollowupEvent[]\n  botSessions      BotSession[]\n  employmentClaims EmploymentClaim[]\n  outcomeEvents    OutcomeEvent[]\n\n  @@index([phoneE164])\n  @@map(\"trainees\")\n}\n\nmodel Enrolment {\n  id                String   @id @default(uuid())\n  traineeId         String\n  cohortId          String\n  certificationDate DateTime\n  createdAt         DateTime @default(now())\n  updatedAt         DateTime @updatedAt\n\n  trainee Trainee @relation(fields: [traineeId], references: [id])\n  cohort  Cohort  @relation(fields: [cohortId], references: [id])\n\n  @@unique([traineeId, cohortId])\n  @@map(\"enrolments\")\n}\n\nmodel FollowupEvent {\n  id             String         @id @default(uuid())\n  traineeId      String\n  cohortId       String\n  checkpointDays Int\n  status         FollowupStatus @default(SCHEDULED)\n  channel        Channel        @default(WHATSAPP)\n  sentAt         DateTime?\n  respondedAt    DateTime?\n  createdAt      DateTime       @default(now())\n  updatedAt      DateTime       @updatedAt\n\n  trainee          Trainee           @relation(fields: [traineeId], references: [id])\n  cohort           Cohort            @relation(fields: [cohortId], references: [id])\n  botSessions      BotSession[]\n  employmentClaims EmploymentClaim[]\n\n  @@index([traineeId, checkpointDays, status])\n  @@map(\"followup_events\")\n}\n\nmodel BotSession {\n  id              String          @id @default(uuid())\n  traineeId       String\n  followupEventId String\n  state           BotSessionState @default(AWAITING_STATUS)\n  currentQuestion String?\n  collectedData   Json            @default(\"{}\")\n  expiresAt       DateTime\n  createdAt       DateTime        @default(now())\n  updatedAt       DateTime        @updatedAt\n\n  trainee       Trainee       @relation(fields: [traineeId], references: [id])\n  followupEvent FollowupEvent @relation(fields: [followupEventId], references: [id])\n\n  @@index([traineeId])\n  @@map(\"bot_sessions\")\n}\n\nmodel EmploymentClaim {\n  id                 String              @id @default(uuid())\n  traineeId          String\n  followupEventId    String\n  employerName       String?\n  role               String?\n  salaryBand         SalaryBand?\n  nonPlacementReason NonPlacementReason?\n  verificationStatus VerificationStatus  @default(SELF_REPORTED)\n  evidenceLevel      Int                 @default(1)\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n\n  trainee              Trainee               @relation(fields: [traineeId], references: [id])\n  followupEvent        FollowupEvent         @relation(fields: [followupEventId], references: [id])\n  verificationRequests VerificationRequest[]\n  outcomeEvents        OutcomeEvent[]\n\n  @@index([traineeId])\n  @@map(\"employment_claims\")\n}\n\nmodel OutcomeEvent {\n  id                 String             @id @default(uuid())\n  traineeId          String\n  employmentClaimId  String?\n  checkpointDays     Int\n  outcomeStatus      OutcomeStatus\n  verificationStatus VerificationStatus\n  source             String // TRAINEE, EMPLOYER, SYSTEM\n  evidenceLevel      Int\n  createdAt          DateTime           @default(now())\n\n  trainee         Trainee          @relation(fields: [traineeId], references: [id])\n  employmentClaim EmploymentClaim? @relation(fields: [employmentClaimId], references: [id])\n\n  @@index([traineeId, checkpointDays, createdAt])\n  @@map(\"outcome_events\")\n}\n\nmodel VerificationRequest {\n  id                String    @id @default(uuid())\n  employmentClaimId String\n  tokenHash         String    @unique\n  expiresAt         DateTime\n  usedAt            DateTime?\n  action            String? // CONFIRMED, REJECTED\n  rejectionReason   String?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  employmentClaim EmploymentClaim @relation(fields: [employmentClaimId], references: [id])\n\n  @@map(\"verification_requests\")\n}\n\nmodel AuditEvent {\n  id         String    @id @default(uuid())\n  entityType String\n  entityId   String\n  action     String\n  actorType  ActorType\n  actorId    String?\n  metadata   Json      @default(\"{}\")\n  createdAt  DateTime  @default(now())\n\n  @@index([entityType, entityId, createdAt])\n  @@map(\"audit_events\")\n}\n\n// Views (optional - backend falls back to raw SQL if not available)\n// model TraineeLatestOutcome {\n//   // v_trainee_latest_outcome\n// }\n//\n// model CohortOverview {\n//   // v_cohort_overview\n// }\n//\n// model Retention {\n//   // v_retention\n// }\n//\n// model WageBands {\n//   // v_wage_bands\n// }\n",
